/**
 * Motion tokens for JavaScript (DESIGN.md §5). Their CSS twins live in styles/tokens.css,
 * and tests/unit/motion.test.ts keeps the two in step, so a value changes in both or the
 * test fails.
 *
 * - Motion (motion/react): `springs.snappy` and `curves.out` drop straight into a transition.
 * - GSAP: `gsapEase("out")` and `gsapSpring("snappy")` give eases with the same shapes.
 * - CSS: the springs ship as `linear()` easings generated by `springLinear()`.
 *
 * Runs under plain Node for tests and generators: no path aliases.
 */

// ─── Curves (§5.1) ───────────────────────────────────────────────────────────

export const curves = {
  out: [0.22, 1, 0.36, 1],
  inOut: [0.65, 0, 0.35, 1],
  emphasized: [0.2, 0, 0, 1],
} as const satisfies Record<string, readonly [number, number, number, number]>;

export type CurveName = keyof typeof curves;

// ─── Springs (§5.2) ──────────────────────────────────────────────────────────

/** SwiftUI-style springs as Motion options: visualDuration in seconds, bounce 0–1. */
export const springs = {
  smooth: { type: "spring", visualDuration: 0.5, bounce: 0 },
  snappy: { type: "spring", visualDuration: 0.35, bounce: 0.15 },
  bouncy: { type: "spring", visualDuration: 0.5, bounce: 0.3 },
  island: { type: "spring", visualDuration: 0.45, bounce: 0.25 },
} as const;

export type SpringName = keyof typeof springs;

// ─── Durations (§5.3), stagger (§5.4) and scrub (§5.5) ───────────────────────

/** Milliseconds. Each DESIGN.md range has a short, default and long step. */
export const durations = {
  /** §5.3 micro: 150–200ms */
  microShort: 150,
  micro: 200,
  /** §5.3 UI: 300–400ms */
  ui: 300,
  uiLong: 400,
  /** §5.3 reveals: 600–900ms. The Resolve uses `reveal`. */
  revealShort: 600,
  reveal: 700,
  revealLong: 900,
  /** The Counter's ceiling: a count-up never runs longer, and no longer than a reveal (Part 17). */
  count: 900,
  /** §5.3 micro: the Island's name swaps with a blur-crossfade this long. */
  swap: 180,
} as const;

export type DurationName = keyof typeof durations;

export const stagger = {
  /** §5.4: lines resolve 60ms apart. */
  lines: 60,
  /** §6.3: Search results resolve 40ms apart. */
  results: 40,
} as const;

/** §5.4 The Resolve: opacity 0→1, blur 12px→0, y 16px→0, scale .98→1. */
export const resolve = {
  blur: 12,
  y: 16,
  scale: 0.98,
  duration: durations.reveal,
  stagger: stagger.lines,
  curve: "out",
} as const;

/** §6.6 Depth on hover: the most a card tilts, and how far its highlight travels (percent). */
export const depth = {
  tilt: 6,
  specularTravel: 25,
} as const;

/** §5.5: seconds a scrubbed value takes to catch up with the scroll. */
export const scrub = 0.6;

/** §5.7: with reduced motion, reveals become fades of this length. */
export const reducedMotionFade = durations.micro;

export const seconds = (ms: number) => ms / 1000;

// ─── Cubic Bézier ────────────────────────────────────────────────────────────

/** A CSS cubic-bezier() as a function of progress, solved the way browsers do. */
export function cubicBezier(x1: number, y1: number, x2: number, y2: number): (t: number) => number {
  const cx = 3 * x1;
  const bx = 3 * (x2 - x1) - cx;
  const ax = 1 - cx - bx;
  const cy = 3 * y1;
  const by = 3 * (y2 - y1) - cy;
  const ay = 1 - cy - by;
  const sampleX = (t: number) => ((ax * t + bx) * t + cx) * t;
  const sampleY = (t: number) => ((ay * t + by) * t + cy) * t;
  const slopeX = (t: number) => (3 * ax * t + 2 * bx) * t + cx;

  const solveT = (x: number) => {
    // Newton's method, then bisection if the slope is too flat to trust.
    let t = x;
    for (let i = 0; i < 8; i++) {
      const error = sampleX(t) - x;
      if (Math.abs(error) < 1e-7) return t;
      const slope = slopeX(t);
      if (Math.abs(slope) < 1e-6) break;
      t -= error / slope;
    }
    let low = 0;
    let high = 1;
    t = x;
    for (let i = 0; i < 40 && high - low > 1e-7; i++) {
      if (sampleX(t) < x) low = t;
      else high = t;
      t = (low + high) / 2;
    }
    return t;
  };

  return (x: number) => (x <= 0 ? 0 : x >= 1 ? 1 : sampleY(solveT(x)));
}

export function cssCurve(name: CurveName): string {
  return `cubic-bezier(${curves[name].join(", ")})`;
}

// ─── Spring physics, matching Motion ─────────────────────────────────────────

interface SpringConfig {
  visualDuration: number;
  bounce: number;
}

/**
 * Motion resolves { visualDuration, bounce } into physics the way SwiftUI does:
 * damping ratio = 1 − bounce, and a natural frequency of 2π / (1.2 · visualDuration),
 * with a mass of 1. The parity test checks this against Motion's own generator.
 */
function physics({ visualDuration, bounce }: SpringConfig) {
  const dampingRatio = Math.max(1 - bounce, 0.05);
  const angularFrequency = (2 * Math.PI) / (visualDuration * 1.2);
  return { dampingRatio, angularFrequency };
}

/** Progress of a spring from 0 to 1 at `t` seconds, starting at rest. */
export function springAt(config: SpringConfig, t: number): number {
  if (t <= 0) return 0;
  const { dampingRatio: zeta, angularFrequency: omega } = physics(config);
  if (zeta < 1) {
    const damped = omega * Math.sqrt(1 - zeta * zeta);
    const envelope = Math.exp(-zeta * omega * t);
    return 1 - envelope * (((zeta * omega) / damped) * Math.sin(damped * t) + Math.cos(damped * t));
  }
  return 1 - Math.exp(-omega * t) * (1 + omega * t);
}

/** Seconds until the spring stays within `epsilon` of its target for good. */
export function springSettle(config: SpringConfig, epsilon = 0.002): number {
  const step = 0.001;
  let lastOutside = 0;
  for (let t = 0; t <= 5; t += step) {
    if (Math.abs(1 - springAt(config, t)) >= epsilon) lastOutside = t;
  }
  return Math.ceil((lastOutside + step) * 100) / 100;
}

/** The spring as a CSS `linear()` easing over its settle time, sampled every ~16ms. */
export function springLinear(config: SpringConfig): string {
  const duration = springSettle(config);
  const count = Math.ceil(duration / 0.016);
  const points: string[] = [];
  for (let i = 0; i <= count; i++) {
    const value = i === count ? 1 : springAt(config, (i / count) * duration);
    points.push(String(Math.round(value * 10000) / 10000));
  }
  return `linear(${points.join(", ")})`;
}

// ─── GSAP ────────────────────────────────────────────────────────────────────

/** A GSAP ease with the exact shape of a DESIGN.md curve. */
export function gsapEase(name: CurveName): (progress: number) => number {
  const [x1, y1, x2, y2] = curves[name];
  return cubicBezier(x1, y1, x2, y2);
}

/** A DESIGN.md spring for GSAP: pass both `duration` and `ease` to a tween. */
export function gsapSpring(name: SpringName): { duration: number; ease: (progress: number) => number } {
  const config = springs[name];
  const duration = springSettle(config);
  return { duration, ease: (progress) => (progress >= 1 ? 1 : springAt(config, progress * duration)) };
}

// ─── Scroll smoothing ────────────────────────────────────────────────────────

/**
 * How far a scrubbed value should move toward its target this frame. It depends on
 * elapsed time, not frame count, so 60 Hz and 120 Hz look identical (§2 rule 6), and it
 * is within 5% of the target after `scrub` seconds (§5.5).
 */
export function scrubStep(elapsedSeconds: number): number {
  return 1 - Math.exp((-3 * elapsedSeconds) / scrub);
}

// ─── Retargetable springs (the cursor's shape) ───────────────────────────────

export interface SpringState {
  value: number;
  /** Units per second. */
  velocity: number;
}

/**
 * Advances a spring toward `target` by `elapsed` seconds, exactly: the closed-form
 * solution of the damped oscillator, so one 1/60s step equals two 1/120s steps and the
 * feel is identical at 60 Hz and 120 Hz (§2 rule 6). It carries velocity, so a target can
 * change mid-flight without a jump.
 */
export function stepSpring(state: SpringState, target: number, elapsed: number, config: SpringConfig): SpringState {
  if (elapsed <= 0) return state;
  const { dampingRatio: zeta, angularFrequency: omega } = physics(config);
  const offset = state.value - target;
  const v0 = state.velocity;
  if (zeta < 1) {
    const damped = omega * Math.sqrt(1 - zeta * zeta);
    const decay = zeta * omega;
    const envelope = Math.exp(-decay * elapsed);
    const cos = Math.cos(damped * elapsed);
    const sin = Math.sin(damped * elapsed);
    const b = (v0 + decay * offset) / damped;
    return {
      value: target + envelope * (offset * cos + b * sin),
      velocity: envelope * ((-decay * offset + damped * b) * cos + (-decay * b - damped * offset) * sin),
    };
  }
  const envelope = Math.exp(-omega * elapsed);
  const c = v0 + omega * offset;
  return {
    value: target + envelope * (offset + c * elapsed),
    velocity: envelope * (v0 - omega * c * elapsed),
  };
}

/** True once a spring is close enough to its target, and slow enough, to stop animating. */
export function springAtRest(state: SpringState, target: number, precision = 0.01): boolean {
  return Math.abs(state.value - target) < precision && Math.abs(state.velocity) < precision * 10;
}
